import axios, { AxiosError } from 'axios';
import { ISerialisedError } from '@game-studio/exceptions';
import { LocalStorage, PartialWithPickRequired } from '@game-studio/utilities';
import { IProvider, ILogstashProviderOptions, IHttpService, IMessageBuilder, Department, ILog } from '../../types';
import { BaseLogVerbosity } from './types';

const THIRTY_SECONDS = 30000;
const MAX_LOGS_TO_SEND = 20;

export abstract class BaseLogstashProvider<Verbosity extends string> implements IProvider {

    protected abstract get storageKey(): string;
    protected abstract get TombolaDocType(): string;
    protected abstract get endpoint(): string;
    protected abstract mapVerbosity(verbosity: BaseLogVerbosity): Verbosity;

    public logsToServer = true;
    protected options: ILogstashProviderOptions;
    protected messageBuilder: IMessageBuilder;
    protected destinations: Department[];
    protected httpService: IHttpService;
    protected logs: Array<ILog<void, Verbosity>>;
    protected locale: string;
    protected operator: string;
    protected scheduled: boolean = false;
    protected scheduleTimeoutId: number | null = null;

    constructor(options: ILogstashProviderOptions, messageBuilder: IMessageBuilder, httpService: IHttpService = axios) {
        this.options = options;
        this.messageBuilder = messageBuilder;
        this.httpService = httpService;
        this.destinations = ['arcade', 'bingo', 'international'];
        this.loadCache();
    }

    public setLocale(locale: string) {
        this.locale = locale;
    }

    public setOperator(operator: string) {
        this.operator = operator;
    }

    public startSchedule() {
        this.scheduled = true;
        this.sendLogs();
    }

    public error(error: ISerialisedError, logToServer?: boolean): void {
        if (!logToServer) {
            return;
        }

        const data = { [`${this.getDataId(error.name)}_data`]: error.data || {} };
        this.logs.push(this.mapMessage(error.name, error.message, this.mapVerbosity('error'), error.stack, data));
        this.saveCache();
    }

    public warn<T extends object | void>(name: string, message: string, data: T): void {
        this.logs.push(this.mapMessage(name, message, this.mapVerbosity('warn'), '', data));
        this.saveCache();
    }

    public info<T extends object | void>(name: string, message: string, data: T): void {
        this.logs.push(this.mapMessage(name, message, this.mapVerbosity('info'), '', data));
        this.saveCache();
    }

    public debug<T extends object | void>(name: string, message: string, data: T): void {
        this.logs.push(this.mapMessage(name, message, this.mapVerbosity('debug'), '', data));
        this.saveCache();
    }

    private getDataId(errorName: string) {
        const eventNameRegex = new RegExp('(?:\\.+|^)([a-z][a-z0-9]+)', 'gim');
        const matches = Array.from(errorName.matchAll(eventNameRegex));

        if (matches.length < 1) {
            return 'unknown';
        }

        const lastMatchIndex = matches.length - 1;
        const lastCaptureIndex = matches[lastMatchIndex].length - 1;
        return matches[lastMatchIndex][lastCaptureIndex];
    }

    private loadCache(): void {
        try {
            const logs = LocalStorage.getItem<ILog<void, Verbosity>[]>(this.storageKey);
            this.logs = logs || [];
        } catch (error) {
            this.logs = this.logs || [];
        }
    }

    private saveCache(): void {
        try {
            LocalStorage.setItem(this.storageKey, this.logs);
        } catch (error) {
            // Ignore failures
        }
    }

    private sendLogs(): void {
        if (this.logs.length === 0) {
            this.scheduleSend();
            return;
        }

        const logsToSend = this.logs.splice(0, MAX_LOGS_TO_SEND);

        this.httpService.post(this.endpoint, logsToSend)
            .catch((error: AxiosError | Error) => {
                this.handleOnSendError(logsToSend, error);
            })
            .then(() => {
                this.saveCache();
                this.scheduleSend();
            });
    }

    protected abstract handleOnSendError(logsToSend: Array<ILog<void, Verbosity>>, error: AxiosError | Error): void;

    public scheduleSend(): void {
        if (!this.scheduled) {
            return;
        }
        this.scheduleTimeoutId = window.setTimeout(() => this.sendLogs(), THIRTY_SECONDS);
    }

    public cancelSchedule(): void {
        this.scheduled = false;
        if (this.scheduleTimeoutId !== null) {
            window.clearTimeout(this.scheduleTimeoutId);
            this.scheduleTimeoutId = null;
        }
    }

    protected mapMessage<T extends object | void>(eventName: string, message: string, verbosity: Verbosity, stack: string = 'empty', data: T = {} as T): ILog<void, Verbosity> {
        return this.constructLog({
            EventName: eventName,
            Message: message,
            Verbosity: verbosity,
            Stack: stack,
            Data: data
        });
    }

    protected constructLog<T>(input: PartialWithPickRequired<ILog<T, Verbosity>, 'Message' | 'Verbosity' | 'EventName'>): ILog<T, Verbosity> {
        return {
            Category: 'Game',
            Country: this.locale,
            Environment: this.options.environment,
            Department: this.operator,
            Operator: this.operator,
            Division: 'game-studio',
            Service: this.options.appName,
            Type: 'log',
            Destinations: this.destinations,
            TombolaDocType: this.TombolaDocType,
            ClientTime: Date.now(),
            Stack: 'empty',
            Data: {},
            DeviceInfo: this.messageBuilder.buildDeviceData(),
            UserInfo: this.messageBuilder.buildUserData(),
            ...input
        };
    }
}
